from datetime import datetime, timedelta

def parse(p):
    ev=[];st=en=None
    for l in open(p):
        l=l.strip()
        if l.startswith('DTSTART'): st=datetime.strptime(l.split(':')[1],'%Y%m%dT%H%M%SZ')
        elif l.startswith('DTEND'):
            en=datetime.strptime(l.split(':')[1],'%Y%m%dT%H%M%SZ'); ev.append((st,en))
    return ev

cal={'alice':parse('/app/alice_calendar.ics'),'bob':parse('/app/bob_calendar.ics'),'carol':parse('/app/carol_calendar.ics')}

def D(m,d,h=0,mi=0): return datetime(2024,m,d,h,mi)

def free_day(person,t):
    day=t.date()
    # base availability windows
    if person=='alice':
        win=[(D(t.month,t.day,9),D(t.month,t.day,14))]
    elif person=='bob':
        win=[(D(t.month,t.day,10),D(t.month,t.day,17))]
        if t.weekday() in (1,3):  # Tue/Thu leave by 16:30
            win=[(D(t.month,t.day,10),min(D(t.month,t.day,16,30),win[0][1]))]
    else:
        win=[(D(t.month,t.day,9),D(t.month,t.day,12)),(D(t.month,t.day,12,30),D(t.month,t.day,17))]
        # 15-min buffer after meetings ending >=16:45 handled by shrinking end if needed (none here)
    return win

def avail(person,s,e):
    for w0,w1 in free_day(person,s):
        if s>=w0 and e<=w1:
            for b0,b1 in cal[person]:
                if s<b1 and b0<e: return False
            return True
    return False

found=None
for d in (15,16,17,18,19):
    t=D(1,d,9)
    while t+timedelta(minutes=60)<=D(1,d,18):
        s,e=t,t+timedelta(minutes=60)
        if all(avail(p,s,e) for p in cal):
            found=(s,e);break
        t+=timedelta(minutes=1)
    if found:break
print('earliest valid:',found, 'weekday:', found[0].strftime('%A') if found else None)

